/** Llull — combinatorial topology governed by the verified Llullian nine-domain
 * rule; not a fractal and not an IFS. Pair/triple inquiry model (D-082 P8).
 * Implements steps 1, 3 and 4 of the Llull rule:
 * the nine-letter alphabet from the
 * codepoint-sorted root domains, the 36 two-letter compartments with exact
 * relation evidence, and the 84 three-letter inquiry rows generated by the
 * Fourth Figure procedure with evidence and hypotheses kept separate. */
import type { TopologyEdge, TopologyNode, TopologySnapshot } from './contract.ts';

/** Ars brevis alphabet: nine letters, no J. */
export const LULL_LETTERS = ['B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'K'] as const;
export const LULL_HISTORICAL_LIMIT = 'Le lettere di Llull indicavano principi predicabili; qui indicano corpora documentali. Il conteggio delle relazioni non prova verità né il medium lulliano. Le 84 triple sono classi deduplicate delle 252 camere della Quarta Figura, non il suo conteggio originale. Fonte: Ramon Llull, Ars brevis, figure A, III e IV (1308).';
export const LULL_SOURCE_CITATION = 'Ramon Llull, Ars brevis (Pisa, 1308), parti I–II, figure A, III e IV; https://www.ramonllull.net/sw_studies/l_br/t_ars.html (consultato 2026-10-05).';
/** Deterministic cap on the path witnesses retained per triple; the exact total
 * stays in `pathWitnessTotal` so the full set remains reproducible. */
export const LULL_PATH_WITNESS_CAP = 24;

const cmp = (a: string, b: string) => a < b ? -1 : a > b ? 1 : 0;

export type LullIndex = Readonly<{ roots: readonly TopologyNode[]; rootOf: ReadonlyMap<string, string>; letterOf: ReadonlyMap<string, string> }>;
export type LullEvidence = Readonly<{ id: string; source: string; target: string; class: TopologyEdge['class']; type: string; directed?: boolean; provenance?: readonly string[] }>;
export type LullPair = Readonly<{ id: string; letters: readonly [string, string]; roots: readonly [string, string]; relationIds: readonly string[]; evidence: readonly LullEvidence[]; weight: number; hypothesis: boolean }>;
/** One generating alignment of the Fourth Figure: the outer fixed letter and the
 * two rotating-wheel letters with their wheel offsets (in ninth-of-a-turn units). */
export type LullWheelPosition = Readonly<{ outer: string; innerOne: string; innerTwo: string; outerIndex: number; innerOneOffset: number; innerTwoOffset: number }>;
export type LullPathWitness = Readonly<{ recordIds: readonly [string, string, string]; relationIds: readonly [string, string] }>;
export type LullTriple = Readonly<{ id: string; letters: readonly [string, string, string]; wheelPositions: readonly LullWheelPosition[]; sharedRecordIds: readonly string[]; pairIds: readonly [string, string, string]; pairRelationIds: readonly (readonly string[])[]; pathWitnesses: readonly LullPathWitness[]; pathWitnessTotal: number; hypothesis: boolean }>;
export type LullInquiry = Readonly<{ digest: string; index: LullIndex; pairs: readonly LullPair[]; triples: readonly LullTriple[]; nodeChords: readonly LullEvidence[]; hypothesesEnabled: false; generatedGraphEdges: 0; reading: string }>;

const domainKey = (rootId: string) => {
  const at = rootId.lastIndexOf(':');
  return at < 0 ? rootId : rootId.slice(at + 1);
};

/** Step 1: freeze and validate the alphabet. Exactly nine root domains (parent
 * null, kind domain, level 1), sorted by Unicode codepoint of their IDs and
 * mapped to B–K; every real node reaches one root through its primary-parent
 * chain. Anything else refuses the Lullian label by throwing. */
export function indexLullSnapshot(snapshot: TopologySnapshot): LullIndex {
  if (!snapshot.digest) throw new Error('lull: full snapshot digest required');
  const nodes = new Map<string, TopologyNode>();
  for (const node of snapshot.nodes) {
    if (nodes.has(node.id)) throw new Error(`lull: duplicate real node ${node.id}`);
    nodes.set(node.id, node);
  }
  const rootList = snapshot.nodes.filter(n => n.parent === null && n.kind === 'domain' && n.level === 1);
  const roots = [...rootList].sort((a, b) => cmp(a.id, b.id));
  const isRoot = new Set(roots.map(r => r.id));
  if (roots.length !== 9 || snapshot.nodes.some(n => n.parent === null && !isRoot.has(n.id)))
    throw new Error(`lull: exactly nine root domains required; found ${roots.length}`);
  const rootOf = new Map<string, string>();
  const resolving = new Set<string>();
  const resolve = (id: string): string => {
    const cached = rootOf.get(id);
    if (cached) return cached;
    if (resolving.has(id)) throw new Error(`lull: primary-parent cycle at ${id}`);
    resolving.add(id);
    const node = nodes.get(id);
    if (!node) throw new Error(`lull: missing primary parent ${id}`);
    const root = isRoot.has(id) ? id : node.parent !== null ? resolve(node.parent) : null;
    resolving.delete(id);
    if (root === null) throw new Error(`lull: ${id} does not reach a root domain`);
    rootOf.set(id, root);
    return root;
  };
  for (const id of nodes.keys()) resolve(id);
  return { roots, rootOf, letterOf: new Map(roots.map((r, i) => [r.id, LULL_LETTERS[i]!])) };
}

const pairKey = (a: string, b: string) => [a, b].sort(cmp).join('');

/** Default reading label when the caller does not name the active reading. */
export const LULL_DEFAULT_READING = 'tutte le relazioni idonee del snapshot completo';

/** Steps 3–4: the inquiry table. `selectedIds` is the density's vertex set V_D
 * (default: every real node); `eligible` filters source relations for the
 * reading (hierarchy counts only when the caller's eligibility includes it) and
 * `reading` labels that active reading for the disclosure surfaces.
 * Every drawn chord carries its exact underlying relation IDs with direction,
 * class, type and provenance; the 36 pairs and 84 triples are inquiry
 * compartments, never graph edges: the hypothesis layer is OFF
 * (`hypothesesEnabled: false`) and `generatedGraphEdges` is 0. */
export function buildLullInquiry(snapshot: TopologySnapshot, options: Readonly<{ index?: LullIndex; selectedIds?: ReadonlySet<string>; eligible?: (edge: TopologyEdge) => boolean; reading?: string }> = {}): LullInquiry {
  const index = options.index ?? indexLullSnapshot(snapshot);
  const selected = options.selectedIds ?? new Set(snapshot.nodes.map(node => node.id));
  const known = new Set(snapshot.nodes.map(node => node.id));
  for (const id of selected)
    if (!known.has(id)) throw new Error('lull: selected ID absent from full snapshot');
  const pairEvidence = new Map<string, LullEvidence[]>();
  const nodeChords: LullEvidence[] = [];
  const seenEdges = new Set<string>();
  for (const edge of snapshot.edges) {
    if (seenEdges.has(edge.id)) throw new Error(`lull: duplicate relation ${edge.id}`);
    seenEdges.add(edge.id);
    if (!known.has(edge.source) || !known.has(edge.target)) throw new Error(`lull: relation ${edge.id} has an unknown endpoint`);
    if (!selected.has(edge.source) || !selected.has(edge.target) || (options.eligible && !options.eligible(edge))) continue;
    // Direction and provenance now live on the contract itself (D082-B5): copy
    // them through unchanged, absent stays absent.
    const evidence: LullEvidence = {
      id: edge.id, source: edge.source, target: edge.target, class: edge.class, type: edge.type,
      ...(edge.directed !== undefined ? { directed: edge.directed } : {}),
      ...(edge.provenance !== undefined ? { provenance: edge.provenance } : {}),
    };
    nodeChords.push(evidence);
    const sourceRoot = index.rootOf.get(edge.source)!;
    const targetRoot = index.rootOf.get(edge.target)!;
    if (sourceRoot !== targetRoot) {
      const key = pairKey(index.letterOf.get(sourceRoot)!, index.letterOf.get(targetRoot)!);
      const list = pairEvidence.get(key) ?? [];
      list.push(evidence);
      pairEvidence.set(key, list);
    }
  }
  nodeChords.sort((a, b) => cmp(a.id, b.id));
  const pairs: LullPair[] = [];
  for (let a = 0; a < 9; a++) for (let b = a + 1; b < 9; b++) {
    const letters: [string, string] = [LULL_LETTERS[a]!, LULL_LETTERS[b]!];
    const evidence = (pairEvidence.get(letters.join('')) ?? []).sort((x, y) => cmp(x.id, y.id));
    pairs.push({ id: `inquiry:pair:${letters.join('')}`, letters, roots: [index.roots[a]!.id, index.roots[b]!.id],
      relationIds: evidence.map(e => e.id), evidence, weight: evidence.length, hypothesis: evidence.length === 0 });
  }
  const pairByKey = new Map(pairs.map(p => [p.letters.join(''), p]));
  // Cross-root eligible chords only: a path witness needs two real relations sharing a
  // middle record, with the three records covering three distinct roots of the triple.
  const byMiddle = new Map<string, LullEvidence[]>();
  for (const edge of nodeChords) {
    const sourceRoot = index.rootOf.get(edge.source)!;
    const targetRoot = index.rootOf.get(edge.target)!;
    if (sourceRoot === targetRoot) continue;
    for (const id of [edge.source, edge.target]) {
      const list = byMiddle.get(id) ?? [];
      list.push(edge);
      byMiddle.set(id, list);
    }
  }
  const triples: LullTriple[] = [];
  for (let a = 0; a < 9; a++) for (let b = a + 1; b < 9; b++) for (let c = b + 1; c < 9; c++) {
    const letters: [string, string, string] = [LULL_LETTERS[a]!, LULL_LETTERS[b]!, LULL_LETTERS[c]!];
    const roots = [index.roots[a]!.id, index.roots[b]!.id, index.roots[c]!.id];
    const rootSet = new Set(roots);
    const pairLetters = [[letters[0], letters[1]], [letters[0], letters[2]], [letters[1], letters[2]]] as const;
    const pairSets = pairLetters.map(key => pairByKey.get(pairKey(key[0], key[1]))!.relationIds);
    const shared = snapshot.nodes
      .filter(n => selected.has(n.id) && roots.every(root => n.domains.includes(root) || n.domains.includes(domainKey(root))))
      .map(n => n.id).sort(cmp);
    const witnesses: LullPathWitness[] = [];
    let pathWitnessTotal = 0;
    for (const [middle, edges] of [...byMiddle].sort((x, y) => cmp(x[0], y[0]))) {
      const middleRoot = index.rootOf.get(middle)!;
      if (!rootSet.has(middleRoot)) continue;
      for (let i = 0; i < edges.length; i++) for (let j = i + 1; j < edges.length; j++) {
        const e1 = edges[i]!, e2 = edges[j]!;
        const left = e1.source === middle ? e1.target : e1.source;
        const right = e2.source === middle ? e2.target : e2.source;
        const leftRoot = index.rootOf.get(left)!;
        const rightRoot = index.rootOf.get(right)!;
        if (leftRoot === middleRoot || rightRoot === middleRoot || leftRoot === rightRoot) continue;
        if (!rootSet.has(leftRoot) || !rootSet.has(rightRoot)) continue;
        pathWitnessTotal++;
        if (witnesses.length < LULL_PATH_WITNESS_CAP)
          witnesses.push({ recordIds: [left, middle, right], relationIds: [e1.id, e2.id] });
      }
    }
    witnesses.sort((x, y) => cmp(x.relationIds.join('\0'), y.relationIds.join('\0')));
    // Fourth Figure generating alignments: the fixed outer letter with the two
    // rotating wheels at their offsets, canonicalised per outer choice.
    const wheelPositions = [a, b, c].map(outer => {
      const inner = [a, b, c].filter(i => i !== outer).sort((x, y) => x - y);
      return { outer: LULL_LETTERS[outer]!, innerOne: LULL_LETTERS[inner[0]!]!, innerTwo: LULL_LETTERS[inner[1]!]!,
        outerIndex: outer, innerOneOffset: (inner[0]! - outer + 9) % 9, innerTwoOffset: (inner[1]! - outer + 9) % 9 };
    });
    triples.push({ id: `inquiry:triple:${letters.join('')}`, letters, wheelPositions,
      sharedRecordIds: shared, pairIds: pairLetters.map(key => `inquiry:pair:${pairKey(key[0], key[1])}`) as [string, string, string],
      pairRelationIds: pairSets, pathWitnesses: witnesses, pathWitnessTotal,
      hypothesis: shared.length === 0 && pathWitnessTotal === 0 });
  }
  return { digest: snapshot.digest, index, pairs, triples, nodeChords, hypothesesEnabled: false, generatedGraphEdges: 0, reading: options.reading ?? LULL_DEFAULT_READING };
}
